"use strict";(self.webpackChunkPromoScreen=self.webpackChunkPromoScreen||[]).push([[434],{93434:e=>{e.exports=JSON.parse('{"reviews":{"get_pregnant":[{"id":"gp_1","text":"App da 5 stelle per la qualità del servizio che ti permette di monitorare la tua ovulazione con ottimi consigli personalizzati.","userName":"rosa caracciolo"},{"id":"gp_2","text":"Ottima app... L\'ho installata un anno dopo aver smesso di prendere la pillola perché volevo rimanere incinta. Avevo un ciclo irregolare... sempre con qualche ritardo. L\'ho seguita alla lettera e adesso sono incinta di sei settimane 😍😍❤❤❤","userName":"andreeabreazu andreea gabriela"},{"id":"gp_3","text":"Ottima app. Grazie a quest\'app ho potuto calcolare l\'ovulazione in maniera perfetta e in 2 mesi di utilizzo sono rimasta incinta... utilissima!","userName":"Neckk1234"}],"track_cycle":[{"id":"tc_1","text":"Davvero utile! Io ho un ciclo irregolare e non so come quest\'app riesca a tenere conto dei giorni nonostante lo stress e i problemi di tutti i giorni. Impeccabile!","userName":"Miriana Panno"},{"id":"tc_2","text":"È molto scorrevole e semplice da utilizzare, ce l\'ho da tempo ormai e sono molto soddisfatta. La migliore in assoluto tra le app per monitorare il ciclo.","userName":"Liana"},{"id":"tc_3","text":"App per noi fanciulle. Davvero ottima. Ora posso prevedere le mestruazioni e capire in base ai miei sintomi che l’arrivo è vicino. È bellissima anche perché mi mostra un report sull’ultimo ciclo e quello attuale.","userName":"gianfilippina paola"}],"follow_pregnancy":[{"id":"fp_1","text":"Utilizzo l\'app in gravidanza e dà dei consigli interessantissimi! La consiglio a tutte!!!!","userName":"Daniela Dell\'Infante"},{"id":"fp_2","text":"Usata per registrare l\'andamento del ciclo e poi per la mia prima gravidanza! App meravigliosa, chiara, piena di informazioni utili e graficamente molto bella!","userName":"Carlotta Zivich"},{"id":"fp_3","text":"Molto pratica. Sono incinta e ogni settimana ricevo le informazioni gestazionali. Sono molto soddisfatta.","userName":"ACR"}]}}')}}]);
